head.script:
    scwin.onpageload = function() {
        var jsonData = [{col1:"afwafewfkjewlfae",col3:"a"},{col1:"c",col3:"c"},{col1:"d",col3:"d"},{col1:"b",col3:"b"}];
        dataList1.setJSON(jsonData);
    };

    scwin.onpageunload = function() {

    };


    scwin.gridView1_ongroupby = function(options) {
        scwin.test(options);
    };
    scwin.test = function(options){
        //debugger;
        var flag = true;
        if(flag) {
            options.closeGroup = true; 

            options.groupbyHeader = [{colSpan: "3", inputType: "expression", expression: " toggle() + depthStr() + ' [ ' + count() + ' 건 ] ' ", align: "left" }];
            options.groupbyFooter = [
                {colSpan:"3",inputType: "expression", expression: " SUM('col2')", displayFormatter: "countFormatFunction", align: "center"}
            ];

            gridView1.groupby( options ); //실제 groupby 실행

        } else {
            return false; 
        }
    }
    var countFormatFunction = function( value ) {
        return "총판매수량 : " + value + " 개 ";
    };

	scwin.fireDbClick = function(node) {
		if (document.createEventObject) {
			node.fireEvent('ondblclick');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function') {
			node.ondblclick();
		}
	}
	scwin.Dbclick = function(id) {
		var el = WebSquare.wUnit.getDomById($p.id + id);
		scwin.fireDbClick(el);
	}

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#gridView1_column1', 'drag-n-drop', {
			dx: 0,
			dy: -30
		});
	}
	scwin.checkVal = function() {
		let tdElement = WebSquare.wUnit.getDomById("gridView1_headerRowNumber_bodyRow_1");
		let bgColor = window.getComputedStyle(tdElement).backgroundColor;
		return bgColor == 'rgb(223, 233, 248)';
	}
	scwin.unitTest = function() {
		//Init test
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_column1').click()");
		WebSquare.wUnit.addCommand("pause", "400");				
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_0').querySelectorAll('span')[1].click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_1_0').click()");
		WebSquare.wUnit.addCommand("pause", "400");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_0').querySelectorAll('span')[1].click()");
		WebSquare.wUnit.addCommand("pause", "400");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run and Stop unit Test
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
